{
  "status": "SUPPORTED",
  "task_summary": "Prepare living room for two people to watch TV and enjoy refreshments.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "refreshment_setting",
        "entity_kind": "OBJECT",
        "function": "Provides drink and food for one person",
        "required_count": 2,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["cup", "plate", "napkin"],
        "required_properties": ["holds_drink", "holds_food"]
      },
      {
        "id": "entertainment_control",
        "entity_kind": "OBJECT",
        "function": "Controls the television",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["remote", "controller"],
        "required_properties": ["controls_tv"]
      },
      {
        "id": "seating_area",
        "entity_kind": "REGION",
        "function": "Area where people sit",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["chair", "sofa", "armchair"],
        "required_properties": ["for_sitting"]
      }
    ],
    "functional_relations": [
      {
        "id": "located_near",
        "relation": "refreshment_setting is located near seating_area",
        "participant_roles": ["refreshment_setting", "seating_area"]
      ,
      "required": true
      },
      {
        "id": "accessible_from",
        "relation": "entertainment_control is accessible from seating_area",
        "participant_roles": ["entertainment_control", "seating_area"]
      ,
      "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "prepare_refreshment_settings",
        "operation": "Set up refreshment settings",
        "participant_roles": ["refreshment_setting", "seating_area"],
        "operation_count": 2
      },
      {
        "id": "position_entertainment_control",
        "operation": "Position entertainment control",
        "participant_roles": ["entertainment_control", "seating_area"],
        "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "refreshment_setting": [
        {"label": "red cup", "visual_description": "Red cup on foreground desk"},
        {"label": "white plate", "visual_description": "White plate on foreground desk"}
      ],
      "entertainment_control": [
        {"label": "black remote", "visual_description": "Black remote on foreground desk"}
      ],
      "seating_area": [
        {"label": "armchair", "visual_description": "Left armchair"},
        {"label": "armchair", "visual_description": "Right armchair"},
        {"label": "coffee table", "visual_description": "Central coffee table"}
      ]
    },
    "inspectable_regions": [
      {
        "id": "desk_table",
        "label": "Foreground desk",
        "visual_description": "Wooden desk with drawers",
        "reason": "Has drawers, could contain additional items."
      },
      {
        "id": "side_tables",
        "label": "Side tables",
        "visual_description": "Small tables next to chairs",
        "reason": "Have shelves, could contain items."
      }
    ],
    "inspection_order": [
      "desk_table",
      "side_tables"
    ]
  }
  ,
